// Parse WorldBank API responses from HTTP nodes + fetch extra indicators
const yieldData = $('Fetch Cereal Yield').first().json;
const prodData = $('Fetch Cereal Production').first().json;

const rows = [];

// Helper: parse WorldBank response array
function parseWB(data) {
  const arr = Array.isArray(data) ? data[1] : (data && data.value ? data.value[1] : []);
  if (arr && Array.isArray(arr)) {
    return arr.find(r => r.value !== null && r.value !== undefined);
  }
  return null;
}

// 1. Cereal Yield (from HTTP node)
const yieldLatest = parseWB(yieldData);
if (yieldLatest) {
  rows.push({ source: 'WorldBank', commodity: 'Rice', metric: 'cereal_yield', value: Math.round(yieldLatest.value * 100) / 100, unit: 'kg/ha', period: yieldLatest.date });
}

// 2. Cereal Production (from HTTP node)
const prodLatest = parseWB(prodData);
if (prodLatest) {
  rows.push({ source: 'WorldBank', commodity: 'Rice', metric: 'cereal_production', value: Math.round(prodLatest.value), unit: 'tonnes', period: prodLatest.date });
}

// 3-7. Extra indicators fetched dynamically (these have data up to 2025!)
const extraIndicators = [
  { code: 'FP.CPI.TOTL.ZG', commodity: 'Economy', metric: 'inflation_cpi', unit: '%' },
  { code: 'NV.AGR.TOTL.ZS', commodity: 'Economy', metric: 'agriculture_pct_gdp', unit: '%' },
  { code: 'SL.AGR.EMPL.ZS', commodity: 'Economy', metric: 'agriculture_employment', unit: '%' },
  { code: 'AG.CON.FERT.ZS', commodity: 'Rice', metric: 'fertilizer_consumption', unit: 'kg/ha arable' },
  { code: 'AG.LND.CREL.HA', commodity: 'Rice', metric: 'cereal_land_area', unit: 'hectares' }
];

for (const ind of extraIndicators) {
  try {
    const url = `https://api.worldbank.org/v2/country/VNM/indicator/${ind.code}?format=json&date=2018:2026&per_page=10`;
    const response = await fetch(url);
    const data = await response.json();
    const latest = parseWB(data);
    if (latest) {
      rows.push({ source: 'WorldBank', commodity: ind.commodity, metric: ind.metric, value: Math.round(latest.value * 100) / 100, unit: ind.unit, period: latest.date });
    }
  } catch (e) { /* skip */ }
}

if (rows.length === 0) {
  return [{ json: { source: 'WorldBank', commodity: 'Economy', metric: 'no_data', value: 0, unit: 'N/A', period: 'N/A' } }];
}

return rows.map(r => ({ json: r }));
